using System; using Cysharp.Threading.Tasks; using TMPro; using UnityEngine; using UnityEngine.EventSystems; using UnityEngine.UI; using UnityEngine.AddressableAssets; using UnityEngine.ResourceManagement.AsyncOperations;
namespace Demo.Inventory { public sealed class InventoryItemView:MonoBehaviour,IBeginDragHandler,IDragHandler,IEndDragHandler { [SerializeField] Image icon; [SerializeField] TMP_Text amountText,nameText; [SerializeField] CanvasGroup canvasGroup; AsyncOperationHandle<Sprite> handle; InventorySlot slot; int position; Action<InventorySlot> click; Action<int,int> drop; public async UniTask BindAsync(InventorySlot s,ItemDefinition d,Action<InventorySlot> c,Action<int,int> onDrop){slot=s;position=s.position;click=c;drop=onDrop;nameText.text=d.itemName;amountText.text=s.amount.ToString();if(d.iconReference==null)return;handle=d.iconReference.LoadAssetAsync<Sprite>();icon.sprite=await handle.Task;icon.enabled=icon.sprite!=null;}public void OnBeginDrag(PointerEventData e){canvasGroup.blocksRaycasts=false;}public void OnDrag(PointerEventData e){transform.position=e.position;}public void OnEndDrag(PointerEventData e){canvasGroup.blocksRaycasts=true;var t=e.pointerEnter?.GetComponentInParent<InventoryItemView>();drop?.Invoke(position,t==null?position:t.position);}public void OnPointerClick(PointerEventData e){click?.Invoke(slot);}public void Clear(){if(handle.IsValid())Addressables.Release(handle);handle=default;click=null;drop=null;}void OnDestroy(){Clear();}} }
